INSERT INTO `exercise` VALUES (1,'杠铃卧推','Barbell Bench Press','卧推,平板卧推,bench',1,1,1,'胸','肱三头肌,三角肌前束',2,1,'仰卧于平板，双眼位于杠铃正下方；肩胛骨后收下沉并全程保持；握距略宽于肩，杠铃下落至乳线位置，小臂垂直地面；推起至肘部接近伸直但不锁死。','肩胛骨不收拢导致肩关节受压；杠铃弹胸借力；臀部离凳；手腕过度后翻。','下放时吸气，推起过粘滞点后呼气。','大重量必须有保护者或安全杠；手腕不要过度后翻，避免腕关节劳损。',0,'2026-10-22 10:03:55','2026-10-27 20:32:12'),(2,'杠铃深蹲','Barbell Back Squat','深蹲,后蹲,背蹲,squat',1,1,3,'股四头肌','臀,腘绳肌,核心',2,1,'杠铃置于斜方肌上，双手窄握收紧背部；下蹲时髋膝同时启动，膝盖沿脚尖方向；下蹲至大腿低于水平或活动度允许的最低位；起身时先抬髋再伸膝。','膝盖内扣；骨盆眨眼（底部腰椎失去中立）；上身过度前倾把重量压到腰；脚跟离地。','下蹲时屏气加压（Valsalva），过粘滞点后呼气换气。','膝内扣是膝关节损伤的主要诱因，可用弹力带套膝辅助；底部骨盆眨眼时应减重或垫高脚跟。',0,'2026-10-22 10:03:55','2026-10-27 20:32:12'),(3,'硬拉','Conventional Deadlift','传统硬拉,deadlift',1,1,4,'腘绳肌','臀,背,股四头肌,前臂',3,1,'站距与髋同宽，杠铃贴近小腿；屈髋屈膝，背部保持中立，手臂垂直；蹬地启动，杠铃全程贴腿上行；锁定髋膝后缓慢下放。','启动瞬间腰部弯曲（圆背硬拉）；杠铃离身体过远导致腰椎力矩剧增；用腰把重量拽起来而非蹬地。','拉起前吸气加压，锁定后呼气。','腰部一旦出现弯曲应立即停止，这是腰椎间盘损伤的高风险动作。',0,'2026-10-22 10:03:55','2026-10-27 20:32:12'),(4,'肩上推举','Overhead Press','站姿推举,肩推,OHP',1,1,1,'肩','肱三头肌,上胸,核心',2,2,'站姿，杠铃置于锁骨上方，手腕在肘正上方；收紧核心与臀部，身体略微后让让杠铃垂直上行；推至过头后肩胛上回旋；下落回到锁骨上方。','腰椎过度反弓代偿；手腕不在肘的正上方导致力线偏移；肩胛未上回旋造成肩峰撞击。','推起过头部后呼气，下落时吸气。','肩关节活动度不足者应改用哑铃或器械推举，避免肩峰撞击。',0,'2026-10-22 10:03:55','2026-10-22 10:03:55'),(5,'引体向上','Pull Up','引体,拉单杠,pullup',4,1,2,'背','肱二头肌,核心',3,1,'双手略宽于肩握杠，肩胛先下沉后收；启动时想象把肘往地面方向拉；上拉至下巴过杠，下放至手臂接近伸直但保持肩胛张力。','用甩身体借力（kipping）；只用小臂和二头拉；下放时完全松掉肩胛。','上拉时呼气，下放时吸气。','肩部有疼痛时应避免颈后引体。',0,'2026-10-22 10:03:55','2026-10-27 20:32:12'),(6,'哑铃卧推','Dumbbell Bench Press','哑铃推胸,哑铃卧推',2,1,1,'胸','肱三头肌,三角肌前束',1,2,'仰卧，双手持哑铃位于胸部两侧，掌心朝前；推起时哑铃向中间靠拢但不碰撞；下放至胸部两侧有拉伸感。','哑铃轨迹过于分散导致肩关节受力过大；下落过快失去控制。','下放吸气，推起呼气。','哑铃卧推的活动度大于杠铃，肩部有伤者需控制下放幅度。',0,'2026-10-22 10:03:55','2026-10-22 10:03:55'),(7,'杠铃划船','Barbell Row','俯身划船,row',1,1,2,'背','肱二头肌,后肩,核心',2,1,'屈髋至上身接近水平，膝盖微屈，腰椎保持中立；将杠铃沿大腿拉向下腹部；顶点挤压肩胛后缓慢放回。','上身角度站得太高变成直立划船；用腰甩动提拉；肩胛没有后缩。','拉起时呼气，放回时吸气。','俯身姿势下腰椎负担大，核心必须全程收紧。',0,'2026-10-22 10:03:55','2026-10-27 20:32:12'),(8,'腿举','Leg Press','倒蹬,腿举,legpress',3,1,3,'股四头肌','臀,腘绳肌',1,2,'坐入器械，双脚踏板与髋同宽；膝盖微屈解锁安全装置；下放至大腿接近躯干，膝盖不要内扣；蹬起时不要锁死膝盖。','下放幅度过大导致骨盆离垫卷起；膝盖内扣；锁死膝关节。','下放吸气，蹬起呼气。','膝关节不要完全锁死，避免压力集中在关节而非肌肉。',0,'2026-10-22 10:03:55','2026-10-22 10:03:55'),(9,'二头弯举','Barbell Curl','弯举,弯举杠铃,手臂',1,2,2,'肱二头肌','前臂',1,2,'站姿，双手肩宽握杠，肘部固定体侧；仅靠肘关节弯曲将杠铃举至肩前；缓慢下放至手臂接近伸直。','甩腰借力（cheat curl）；肘部前移让三角肌前束代偿；下放过快。','弯举时呼气，下放时吸气。','肘部位置必须固定，前移会让发力转移到肩部。',0,'2026-10-22 10:03:55','2026-10-22 10:03:55'),(10,'绳索下压','Triceps Pushdown','三头下压,臂屈伸,tricep',5,2,1,'肱三头肌','',1,2,'站姿，双手握绳或直杆，肘部夹紧体侧；仅靠肘关节伸展向下压至手臂接近伸直；缓慢回到起始位。','肘部外展让背阔肌代偿；身体前倾借力；下压过猛。','下压时呼气，回位时吸气。','肘部全程贴住躯干是发力的关键。',0,'2026-10-22 10:03:55','2026-10-22 10:03:55'),(2115004547127373825,'上斜杠铃卧推','Incline Bench Press','上斜卧推,上斜推',1,1,NULL,'胸',NULL,2,2,NULL,NULL,NULL,NULL,0,'2026-10-27 16:55:53','2026-10-27 16:55:53'),(2115004547215454209,'下斜杠铃卧推','Decline Bench Press','下斜卧推',1,1,NULL,'胸',NULL,2,2,NULL,NULL,NULL,NULL,0,'2026-10-27 16:55:53','2026-10-27 16:55:53'),(2115004547274174465,'哑铃飞鸟','Dumbbell Fly','飞鸟,夹胸',2,1,NULL,'胸',NULL,2,3,NULL,NULL,NULL,NULL,0,'2026-10-27 16:55:53','2026-10-27 20:32:13'),(2115004547320311810,'器械推胸','Chest Press Machine','推胸器,坐姿推胸',3,1,NULL,'胸',NULL,2,2,NULL,NULL,NULL,NULL,0,'2026-10-27 16:55:53','2026-10-27 16:55:53'),(2115004547395809281,'高位下拉','Lat Pulldown','下拉,背阔下拉',3,1,NULL,'背',NULL,2,2,NULL,NULL,NULL,NULL,0,'2026-10-27 16:55:53','2026-10-27 16:55:53'),(2115004547450335233,'坐姿划船','Seated Cable Row','绳索划船',5,1,NULL,'背',NULL,2,2,NULL,NULL,NULL,NULL,0,'2026-10-27 16:55:53','2026-10-27 16:55:53'),(2115004547504861186,'单臂哑铃划船','One Arm Dumbbell Row','哑铃划船',2,1,NULL,'背',NULL,2,2,NULL,NULL,NULL,NULL,0,'2026-10-27 16:55:53','2026-10-27 16:55:53'),(2115004547559387138,'前蹲','Front Squat','前蹲,前杠深蹲',1,1,NULL,'股四头肌',NULL,2,2,NULL,NULL,NULL,NULL,0,'2026-10-27 16:55:53','2026-10-27 16:55:53'),(2115004547618107394,'罗马尼亚硬拉','Romanian Deadlift','RDL,直腿硬拉',1,1,NULL,'腘绳肌',NULL,2,2,'微屈膝；杠贴腿向下滑，感受腘绳与臀拉伸，至躯干近平行再髋驱动站起。','膝盖过度弯曲变普通硬拉、圆背、杠离腿。','下放吸气，站起呼气。','腘绳柔韧性差先减小行程。',0,'2026-10-27 16:55:53','2026-10-28 11:46:57'),(2115004547681021953,'腿弯举','Leg Curl','腿弯,腘绳弯举',3,1,NULL,'腘绳肌',NULL,2,3,'俯卧或坐姿固定；在控制下弯曲膝关节，顶峰稍停再慢放。','借髋抬起、重量砸回、行程只有一半。','弯起呼气，放下吸气。','膝痛减重量或改髋铰链腘绳训练。',0,'2026-10-27 16:55:53','2026-10-28 11:46:57'),(2115004547735547906,'腿伸展','Leg Extension','腿屈伸,踢腿',3,1,NULL,'股四头肌',NULL,2,3,NULL,NULL,NULL,NULL,0,'2026-10-27 16:55:53','2026-10-27 20:32:13'),(2115004547777490946,'杠铃肩推','Overhead Press','肩推,推举,OHP',1,1,NULL,'肩',NULL,2,1,'杠置于锁骨前；核心收紧；垂直向上推至肘伸直，下落控制回锁骨。','过度后仰借力、肘过度打开、推到脑后压肩。','推起呼气，下落吸气。','肩峰撞击感改哑铃或减幅度。',0,'2026-10-27 16:55:53','2026-10-28 11:46:57'),(2115004547823628290,'哑铃肩推','Dumbbell Shoulder Press','哑铃推举,坐姿肩推',2,1,NULL,'肩',NULL,2,2,NULL,NULL,NULL,NULL,0,'2026-10-27 16:55:53','2026-10-27 16:55:53'),(2115004547869765634,'侧平举','Lateral Raise','侧平举',2,1,NULL,'肩',NULL,2,3,'肘微屈；大臂外展至约与肩平，小拇指略高于拇指，慢下放。','借甩躯干、举过头顶、耸肩代劳。','举起呼气，放下吸气。','肩不适改绳索面拉或减重量。',0,'2026-10-27 16:55:53','2026-10-28 11:46:57'),(2115004547915902978,'面拉','Face Pull','面拉,绳索面拉',5,1,NULL,'肩',NULL,2,3,'绳索与眼同高；拉向脸侧，外旋前臂，肘高于手，肩胛后收。','变成高位下拉、耸肩、只用手臂拉。','拉回呼气，回放吸气。','肩袖友好动作，可放热身或练后。',0,'2026-10-27 16:55:53','2026-10-28 11:46:58'),(2115004547962040321,'杠铃弯举','Barbell Curl','二头弯举,弯举',1,1,NULL,'肱二头肌',NULL,2,3,NULL,NULL,NULL,NULL,0,'2026-10-27 16:55:53','2026-10-27 20:32:13'),(2115004548003983361,'哑铃弯举','Dumbbell Curl','哑铃弯举,交替弯举',2,1,NULL,'肱二头肌',NULL,2,3,NULL,NULL,NULL,NULL,0,'2026-10-27 16:55:53','2026-10-27 20:32:13'),(2115004548054315010,'锤式弯举','Hammer Curl','锤式',2,1,NULL,'肱二头肌',NULL,2,3,NULL,NULL,NULL,NULL,0,'2026-10-27 16:55:53','2026-10-27 20:32:13'),(2115004548100452354,'仰卧臂屈伸','Skull Crusher','仰卧屈伸',1,1,NULL,'肱三头肌',NULL,2,3,NULL,NULL,NULL,NULL,0,'2026-10-27 16:55:53','2026-10-27 20:32:13'),(2115004548142395393,'双杠臂屈伸','Dip','双杠撑,臂屈伸',4,1,NULL,'肱三头肌',NULL,2,3,NULL,NULL,NULL,NULL,0,'2026-10-27 16:55:53','2026-10-27 20:32:13'),(2115004548192727042,'平板支撑','Plank','平板,plank',4,1,NULL,'腹',NULL,2,3,NULL,NULL,NULL,NULL,0,'2026-10-27 16:55:53','2026-10-27 20:32:13'),(2115004548243058689,'卷腹','Crunch','卷腹',4,1,NULL,'腹',NULL,2,3,NULL,NULL,NULL,NULL,0,'2026-10-27 16:55:53','2026-10-27 20:32:13'),(2115004548289196034,'悬垂举腿','Hanging Leg Raise','悬垂抬腿',4,1,NULL,'腹',NULL,2,3,NULL,NULL,NULL,NULL,0,'2026-10-27 16:55:53','2026-10-27 20:32:13'),(2115004548297584641,'臀桥','Hip Thrust','臀桥,髋推',1,1,NULL,'臀',NULL,2,2,'上背靠凳、杠或垫落髋；脚跟发力把髋推到肩膝一线，顶峰挤臀。','用腰过度反弓、膝盖外崩或内扣、行程过短。','推起呼气，下放吸气。','下背代偿时减小行程并收肋。',0,'2026-10-27 16:55:53','2026-10-28 11:46:58');
