  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_phone_deleted` (`phone`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='会员';
