DROP TABLE IF EXISTS `rag_doc_chunk`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `rag_doc_chunk` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `doc_name` varchar(128) NOT NULL,
  `doc_md5` char(32) NOT NULL COMMENT '文档 MD5，用于入库判重',
  `doc_type` tinyint NOT NULL COMMENT '1动作库 2训练原则 3营养',
  `section_no` varchar(64) DEFAULT NULL COMMENT '章节号，写入向量库 metadata',
  `title` varchar(255) DEFAULT NULL,
  `content` text NOT NULL,
  `token_count` int DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_md5_section` (`doc_md5`,`section_no`),
  KEY `idx_doc_type` (`doc_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='知识库切片';
